---
import Text from "@/components/fundations/typography/Text.astro";
const stats = [
  {
    label: "Working Individuals",
    value: "30%",
  },
  {
    label: "Super low fee",
    value: "40%",
  },
  {
    label: "Great Commitment",
    value: "50%",
  },
  {
    label: "Massive Earnings",
    value: "60M",
  },
];
---

<section class="bg-white ">
  <div class="px-8 py-24 mx-auto max-w-7xl md:px-12 lg:px-20">
    <div
      class="text-center grid grid-cols-1 gap-x-4 gap-y-12 sm:grid-cols-2 md:grid-cols-4"
    >
      {
        stats.map((stat) => (
          <div class="flex flex-col">
            <Text
              tag="h3"
              variant="displayXL"
              class="font-mono text-primary "
            >
              {stat.value}
            </Text>

            <Text
              tag="h3"
              variant="textBase"
              class="font-semibold text-base-900 "
            >
              {stat.label}
            </Text>
          </div>
        ))
      }
    </div>
  </div>
</section>
